class Solution {public int[] solve(String text,String pattern){if(pattern.length()==0)return new int[0];int[] want=new int[26],have=new int[26];for(char c:pattern.toCharArray())want[c-'a']++;ArrayList<Integer> out=new ArrayList<>();for(int r=0;r<text.length();r++){have[text.charAt(r)-'a']++;if(r>=pattern.length())have[text.charAt(r-pattern.length())-'a']--;if(r>=pattern.length()-1&&Arrays.equals(want,have))out.add(r-pattern.length()+1);}int[] answer=new int[out.size()];for(int i=0;i<answer.length;i++)answer[i]=out.get(i);return answer;}}